package com.fathom.investment; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.*; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController public class InvestmentController { private final InvestmentHoldingRepository repo; public InvestmentController(InvestmentHoldingRepository repo){this.repo=repo;} record Req(@NotNull AssetType assetType,@NotBlank String name,String provider,String symbol,String currency,@DecimalMin("0.0") BigDecimal investedAmount,@DecimalMin("0.0") BigDecimal currentValue,LocalDate asOfDate){} record Res(UUID id,UUID userId,AssetType assetType,String name,BigDecimal investedAmount,BigDecimal currentValue,boolean active,Instant createdAt,Instant updatedAt){}
@PostMapping("/api/users/{userId}/investment-holdings") Res create(@PathVariable UUID userId,@Valid @RequestBody Req r){ InvestmentHolding i=new InvestmentHolding(); i.setUserId(userId); i.setAssetType(r.assetType()); i.setName(r.name()); i.setProvider(r.provider()); i.setSymbol(r.symbol()); if(r.currency()!=null)i.setCurrency(r.currency()); if(r.investedAmount()!=null)i.setInvestedAmount(r.investedAmount()); if(r.currentValue()!=null)i.setCurrentValue(r.currentValue()); i.setAsOfDate(r.asOfDate()); return m(repo.save(i)); }
@GetMapping("/api/users/{userId}/investment-holdings") List<Res> list(@PathVariable UUID userId){ return repo.findByUserId(userId).stream().map(this::m).toList(); }
private Res m(InvestmentHolding i){return new Res(i.getId(),i.getUserId(),i.getAssetType(),i.getName(),i.getInvestedAmount(),i.getCurrentValue(),i.isActive(),i.getCreatedAt(),i.getUpdatedAt());}}
